type AwakeCallback = () => void;
type SleepCallback = () => void;
type ResumeCallback = () => void;
type PauseCallback = () => void;
type QuitCallback = () => void;
type BackButtonCallback = () => void;
/**
 * Why the player's identity changed mid-session:
 * - `sign_in`        — anonymous → authenticated, SAME profile.id (linkWithCredential)
 * - `account_switch` — profile.id changed (signed into a different existing account)
 * - `sign_out`       — authenticated → anonymous
 */
type IdentityChangeReason = 'sign_in' | 'account_switch' | 'sign_out';
interface IdentityChangedEvent {
    /** Identity now in effect. After `sign_in`, `isAnonymous === false`. */
    profile: Profile;
    /** Identity in effect immediately before; `null` if unknown. */
    previousProfile: Profile | null;
    reason: IdentityChangeReason;
    /** `previousProfile?.id !== profile.id` — game state keyed on the old id is now orphaned. */
    idChanged: boolean;
}
type IdentityChangedCallback = (event: IdentityChangedEvent) => void;
interface LifecycleApi {
    /**
     * Registers a callback for when the game transitions from "idle" to "active" state.
     *
     * This occurs when the game comes to the foreground. Use this to load heavy resources
     * or resume activities that were paused during sleep.
     *
     * @param callback - Function to execute when the game awakens
     * @returns Subscription object that can be used to unsubscribe from the event
     */
    onAwake(callback: AwakeCallback): Subscription;
    /**
     * Registers a callback for when the game transitions from "active" to "idle" state.
     *
     * This occurs when the game goes to the background. Use this to unload heavy resources,
     * save state, or pause non-essential activities.
     *
     * @param callback - Function to execute when the game goes to sleep
     * @returns Subscription object that can be used to unsubscribe from the event
     */
    onSleep(callback: SleepCallback): Subscription;
    /**
     * Registers a callback for when gameplay should resume.
     *
     * This occurs when the platform dismisses dialogs or overlays, or when players
     * return from a temporary switch. Use this to resume game logic and animations.
     *
     * @param callback - Function to execute when gameplay resumes
     * @returns Subscription object that can be used to unsubscribe from the event
     */
    onResume(callback: ResumeCallback): Subscription;
    /**
     * Registers a callback for when gameplay should pause.
     *
     * This occurs when the platform brings up dialogs or overlays, or when players
     * temporarily switch away. Use this to pause game logic and animations.
     *
     * @param callback - Function to execute when gameplay pauses
     * @returns Subscription object that can be used to unsubscribe from the event
     */
    onPause(callback: PauseCallback): Subscription;
    /**
     * Registers a callback for final teardown before the game instance is destroyed.
     *
     * This is the last chance to clean up resources, save state, and perform any
     * necessary cleanup before the game instance is destroyed or replaced.
     *
     * @param callback - Function to execute during cleanup
     * @returns Subscription object that can be used to unsubscribe from the event
     */
    onQuit(callback: QuitCallback): Subscription;
    /**
     * Registers a callback for when the user presses the device back button (Android only).
     *
     * Use this to navigate back within your game's own UI or show an exit
     * confirmation. If you want the host to perform its default quit behavior,
     * call `RundotGameAPI.requestPopOrQuit()` from within the callback.
     *
     * On platforms without a hardware back button (iOS, web), this event never fires,
     * but registering a handler is safe and acts as a no-op.
     *
     * @param callback - Function to execute when the back button is pressed
     * @returns Subscription object that can be used to unsubscribe from the event
     */
    onBackButton(callback: BackButtonCallback): Subscription;
    /**
     * Registers a callback for when the player's identity changes mid-session
     * (e.g. an anonymous player signs in without the game reloading).
     *
     * The host preserves the running game; this event lets the game react —
     * re-render the avatar, refetch user-scoped state, or re-issue a request
     * that previously required authentication. By the time the callback fires,
     * `RundotGameAPI.profile` already reflects the new identity.
     *
     * @param callback - Function to execute when identity changes
     * @returns Subscription object that can be used to unsubscribe from the event
     */
    onIdentityChanged(callback: IdentityChangedCallback): Subscription;
}

