/**
 * SDK-owned opaque replay blob for leaderboard submission. Deliberately NOT the
 * syncplay `ReplayFile` type — that embeds `KinetixRuntimeIdentity`, which would
 * pull kinetix back into the SDK. `object` (not `Record<string, unknown>`) so an
 * interface like syncplay's `ReplayFile` — which has no index signature — is
 * assignable at the consumer call site without a cast. The SDK only attaches and
 * size-checks the serialized replay.
 */
type LeaderboardReplay = object;

interface ScoreToken {
    token: string;
    startTime: number;
    expiresAt: number;
    sealingNonce?: string | null;
    sealingSecret?: string | null;
    mode: string;
}
interface SubmitScoreParams {
    token?: string;
    score: number;
    duration: number;
    mode?: string;
    period?: string;
    telemetry?: Record<string, any>;
    metadata?: Record<string, any>;
    /**
     * Score-sealing hash. Auto-computed by RpcLeaderboardApi when the score token
     * carries a sealing nonce/secret; hosts forward it to the backend. Sealed
     * leaderboards reject submissions without a valid hash.
     */
    hash?: string;
    /**
     * The player's recorded syncplay replay (inputs + seed). Required for a
     * `requiresReplay` board: the server re-runs the certified score runtime over
     * these inputs and only ranks the score on a match. Attach it from
     * `session.exportReplay()`. A replay serializing above the inline cap
     * ({@link REPLAY_INLINE_MAX_BYTES}) is rejected client-side before submitting.
     */
    replay?: LeaderboardReplay;
}
/**
 * Machine-readable reason a submit was not accepted.
 * - `identity_changed`: the score token was minted under a different identity
 *   (the player signed into another account mid-session). Re-mint with
 *   `createScoreToken()` and resubmit under the new identity.
 * - `replay_rejected`: a `requiresReplay` board could not verify the submitted
 *   score against the recorded replay (mismatch, invalid/missing replay, or the
 *   verifier was unavailable). The score was NOT ranked. Surface it as the
 *   terminal "rejected" state of the optimistic pending → ranked/rejected UX.
 */
type SubmitScoreFailureReason = 'identity_changed' | 'replay_rejected';
interface SubmitScoreResult {
    accepted: boolean;
    rank?: number | null;
    zScore?: number | null;
    isAnomaly?: boolean;
    /** Human-readable explanation when `accepted` is false (e.g., keep-best rejection). */
    reason?: string | null;
    /** Machine-readable failure reason the game can branch on, when applicable. */
    failureReason?: SubmitScoreFailureReason;
}
