interface Entitlement {
    docId: string;
    userId: string;
    gameId: string;
    entitlementId: string;
    quantity: number;
    consumable: boolean;
    status: 'active' | 'revoked' | 'expired';
    expiresAt: number | null;
    createdAt: number;
    updatedAt: number;
    revokedAt: number | null;
}
interface LedgerEntry {
    ledgerId: string;
    userId: string;
    gameId: string;
    entitlementId: string;
    change: number;
    action: 'grant' | 'consume' | 'revoke' | 'expire';
    source: string;
    referenceId: string;
    reason: string | null;
    createdAt: number;
    balanceAfter: number;
}
interface EntitlementApi {
    /** Get all active entitlements for the current game */
    listEntitlements(): Promise<Entitlement[]>;
    /** Get current quantity for a specific entitlement */
    getQuantity(entitlementId: string): Promise<number>;
    /**
     * Consume quantity from a consumable entitlement.
     *
     * A unique referenceId is generated internally for idempotency unless one is
     * provided. If a callback is supplied it is invoked exactly once on success
     * with the resulting entitlement and the referenceId that was used. If the
     * callback throws, the error is logged as a warning and the entitlement is
     * still returned.
     *
     * **Retry pattern** – make the first call without a referenceId and capture
     * it in the callback. If the callback or any post-consume work fails, retry
     * with the same referenceId so the server treats the request as idempotent:
     *
     * ```ts
     * let savedRefId: string | undefined
     * try {
     *   await api.consumeEntitlement('coins', 10, (_ent, refId) => {
     *     savedRefId = refId
     *     riskyOperation() // may throw
     *   })
     * } catch {
     *   // retry with the same referenceId – the server won't double-consume
     *   await api.consumeEntitlement('coins', 10, undefined, undefined, savedRefId)
     * }
     * ```
     */
    consumeEntitlement(entitlementId: string, quantity: number, callback?: (entitlement: Entitlement, referenceId: string) => void | Promise<void>, reason?: string, referenceId?: string): Promise<Entitlement>;
    /** Get ledger entries (audit trail) */
    getLedger(entitlementId?: string, limit?: number, startAfter?: number): Promise<LedgerEntry[]>;
}

/**
 * Choices partner-integration namespace: read/spend the current user's
 * Choices diamond balance from an authenticated game.
 *
 * Accessing this surface requires two conditions to be met on the venus
 * side (`/v1/choices/*`, see the choices-s2s design doc):
 *
 *   1. The `run_tv_choices_diamonds_enabled` Statsig gate is on.
 *   2. The calling game's game-session-token `gid` claim is on the
 *      hardcoded allowlist (currently only run-tv). Any other game in
 *      the RUN catalog is 403'd.
 *
 * Linking (writing the `uid → altId` mapping) is NOT exposed here — the
 * host's Choices ingress deeplink handler calls `POST /v1/choices/link`
 * directly, mirroring how `choicesVip` grants its entitlement. Games see
 * a linked user (`getBalance` succeeds) or a not-linked user
 * (`getBalance` rejects with `NOT_LINKED`); they never trigger the link
 * themselves.
 */
interface ChoicesBalance {
    /** Current Choices diamond balance for the authenticated user. */
    diamonds: number;
}
interface ChoicesSpendRequest {
    /** Positive integer, bounded server-side to a per-call ceiling. */
    amount: number;
    /**
     * Free-form audit tag, e.g. `episode_unlock:curse_of_marble_ep3`.
     * Stored in the Choices ledger and this SDK's own logs; not
     * user-facing.
     */
    reason: string;
    /**
     * Stable identifier for this logical spend action. Must be reused
     * verbatim across manual retries within one user action so the
     * server-side idempotency layer replays the original outcome
     * instead of double-deducting. Generate a fresh UUID for each new
     * action; reuse across every retry attempt of that same action.
     */
    clientRequestId: string;
}
interface ChoicesSpendResult {
    /** Balance after the deduct (or the replayed original balance). */
    newDiamonds: number;
    /** The amount actually debited from the Choices wallet. */
    amountDebited: number;
    /**
     * Opaque handle to the Choices ledger row for this spend — value is
     * the upstream idempotency key. Surface in support UIs; not
     * meaningful to game logic.
     */
    transactionRef: string;
    /**
     * `true` when the server replayed a prior successful spend rather
     * than debiting again (i.e. this retry saw the ledger already
     * committed). Callers can use it to distinguish "we did the thing"
     * from "we already did the thing" for UX polish.
     */
    alreadyProcessed: boolean;
}
interface ChoicesApi {
    /**
     * Fetch the authenticated user's current Choices diamond balance.
     *
     * Rejects (`RundotApiError`) with:
     *   - `NOT_LINKED` (403) — user hasn't linked; UI should hide the
     *     Choices spend option.
     *   - `SERVICE_UNAVAILABLE` (503) — the integration Statsig gate
     *     is off; treat as "feature disabled".
     *   - `FORBIDDEN` (403) — this game isn't on the allowlist. Bug —
     *     surface to error reporting.
     *   - `UPSTREAM_ERROR` (502) — Choices reachability / mapping issue.
     *   - `RATE_LIMITED` (429) — honor `Retry-After` header.
     */
    getBalance(): Promise<ChoicesBalance>;
    /**
     * Spend Choices diamonds against the current user's wallet. Server
     * idempotency guarantees that reusing the same `clientRequestId`
     * within a retry window returns the original outcome — never
     * double-charges.
     *
     * Rejects (`RundotApiError`) with:
     *   - `INSUFFICIENT_FUNDS` (402) — balance too low; expected UX
     *     outcome, not an error.
     *   - `INVALID_AMOUNT` (400) — amount ≤ 0 or above server ceiling.
     *   - `MALFORMED_REQUEST` (400) — missing/empty `reason` or
     *     `clientRequestId`.
     *   - `IN_PROGRESS` (409) — same `clientRequestId` is currently
     *     being processed on the server; back off and retry with the
     *     same key.
     *   - `NOT_LINKED` / `SERVICE_UNAVAILABLE` / `FORBIDDEN` /
     *     `UPSTREAM_ERROR` / `RATE_LIMITED` — same semantics as
     *     `getBalance`.
     */
    spend(request: ChoicesSpendRequest): Promise<ChoicesSpendResult>;
}

/**
 * Information returned when a stat submission triggers one or more rule
 * evaluations server-side. Mirrors the cloud-run GrantInfo type in
 * server/cloud-run/src/types/collectibles.ts.
 *
 * Most submissions resolve with an empty `grants` array — only stats wired to
 * a collectible rule produce grants. RUN.tv consumers use `grants` to drive
 * the reveal overlay; fire-and-forget callers can ignore it.
 */
interface GrantInfo {
    /** Card identifier (= entitlementId on the platform). */
    cardId: string;
    /** Rule that fired to produce this grant. */
    ruleId: string;
    /** Card type from the catalog. 'vip' and 'premium' grants do not flow
     *  through stats.submit and so do not appear here. */
    type: 'free' | 'completion';
    /** Source of the trigger for analytics attribution. */
    source: 'watch' | 'completion_reward';
}
interface StatsApi {
    /**
     * Submit a stat value for the current user in this game. Schemaless — any
     * `(statId, value)` pair is accepted. The server stores last-write-wins.
     *
     * Resolves with `{ grants }` containing the cards granted by rule evaluation
     * for **this specific statId**. The array is empty for stats with no rules,
     * or when this stat's rules did not fire.
     *
     * Submits issued within the same synchronous tick coalesce into a single
     * round-trip (per-stat last-write-wins on `value`). Each caller's promise
     * resolves or rejects based on their own statId's outcome — callers do not
     * observe grants from other stats in the same batch, even if one is
     * submitted next to theirs.
     *
     * For most game use cases the result can be ignored — the platform records
     * grants server-side regardless and consumers (like RUN.tv's Profile)
     * refresh entitlements on a separate cadence. Consumers that drive a
     * reveal-overlay UX synchronous with the submit await the grants.
     */
    submit(statId: string, value: number): Promise<{
        grants: GrantInfo[];
    }>;
    /** Get the current value of a stat, or `null` if never submitted. */
    getValue(statId: string): Promise<number | null>;
    /** Get all stat values for the current user in this game as a flat map. */
    getAllValues(): Promise<Record<string, number>>;
}

/**
 * Card catalog entry. Mirrors the cloud-run CollectibleCard shape — the same
 * data that gets authored in a game's `.rundot/collectibles.config.json`.
 *
 * The SDK does not interpret these fields; they are passed through to the
 * consumer for rendering. `artPath` / `thumbPath` are CDN-relative — resolve
 * them via `RundotGameAPI.cdn.resolveAssetUrl` before display.
 */
interface CollectibleCard {
    cardId: string;
    storyId: string;
    episodeId?: string;
    type: 'free' | 'premium' | 'vip' | 'completion';
    rarity: 'common' | 'rare' | 'epic' | 'legendary';
    title: string;
    description: string;
    artPath: string;
    thumbPath: string;
    lockedArtPath?: string;
    priceRbOverride?: number;
    limitedTimeEnd?: string;
}
/** Result of a VIP card claim. */
interface VipClaimResult {
    granted: boolean;
    cardId: string;
}
interface CollectiblesApi {
    /**
     * Fetch the deployed card catalog for the current game. Returns every card
     * authored in `.rundot/collectibles.config.json` — both owned and unowned
     * from the user's perspective. Pair with `RundotGameAPI.entitlements.*` to
     * decide which cards the player currently owns.
     *
     * Typically called once on game init and cached client-side; the catalog
     * only changes on the next `rundot deploy`.
     */
    listCards(): Promise<CollectibleCard[]>;
    /**
     * Claim a VIP card for the current user. The server validates that the
     * user is an active subscriber AND has completed the requested series (via
     * the `series_completed_{seriesId}` stat), then grants the matching card
     * entitlement directly — no rule engine, no client-writable trigger stat
     * in between.
     *
     * Rejects with an error when the server returns 403 (subscription required)
     * or 400 (series not completed / card mismatch / unknown card). Consumers
     * typically translate the error message into a toast.
     */
    claimVipCard(seriesId: string, cardId: string): Promise<VipClaimResult>;
}

